// Parse the Anthropic Messages API response, merge with the profile
// from Strip HTML, compute needs_review, and build the ClickUp task
// name + markdown description. Robust to upstream failures — on any
// parsing error, falls back to empty arrays and flags for Arin.

const profile = $('Strip HTML').item.json;
const current = $json || {};

// Anthropic /v1/messages response shape: { content: [ { type: 'text', text: '...' } ], ... }
let raw = '';
if (Array.isArray(current.content)) {
  const textBlock = current.content.find(c => c && c.type === 'text');
  if (textBlock && typeof textBlock.text === 'string') raw = textBlock.text;
} else if (typeof current.text === 'string') {
  raw = current.text;
}

let classified = { facilities: [], amenities: [] };
try {
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    if (Array.isArray(parsed.facilities)) classified.facilities = parsed.facilities;
    if (Array.isArray(parsed.amenities)) classified.amenities = parsed.amenities;
  }
} catch (e) {
  // swallow — empty arrays + needs_review will flag it
}

const needsReview = Boolean(
  profile._parseFailed ||
  (!profile.website && !profile.instagram) ||
  profile._fetchEmpty ||
  (classified.facilities.length === 0 && classified.amenities.length === 0)
);

const fmt = v => (v === null || v === undefined || v === '') ? '—' : v;
const fmtList = a => (Array.isArray(a) && a.length) ? a.map(x => '- ' + x).join('\n') : '—';

const reasons = [
  profile._parseFailed && 'extraction failed',
  (!profile.website && !profile.instagram) && 'no website or Instagram',
  profile._fetchEmpty && 'site content empty',
  (classified.facilities.length === 0 && classified.amenities.length === 0) && 'no facilities/amenities matched'
].filter(Boolean);

const reviewBanner = needsReview
  ? `> **Needs review** — arin.melvin@boddy.tech\n> Reasons: ${reasons.join('; ')}\n\n`
  : '';

const body = `${reviewBanner}## About\n${fmt(profile.description)}\n\n## Contact\n- Name: ${fmt(profile.contact_name)}\n- Role: ${fmt(profile.contact_role)}\n- Email: ${fmt(profile.contact_email)}\n- Phone: ${fmt(profile.contact_phone)}\n\n## Location\n${fmt(profile.location_city)}, ${fmt(profile.location_country)}\n\n## Business\n- Type: ${fmt(profile.business_type)}\n- Website: ${fmt(profile.website)}\n- Instagram: ${fmt(profile.instagram)}\n\n## Facilities\n${fmtList(classified.facilities)}\n\n## Amenities\n${fmtList(classified.amenities)}\n\n## Pricing\n${fmtList(profile.pricing_details)}\n\n## Contract\n${fmt(profile.contract_type)}\n\n---\nSource file: ${fmt(profile._sourceFileName)}`;

const name = (needsReview ? '[REVIEW — Arin] ' : '') + (profile.business_name || 'New Partner');

return [{
  json: {
    task_name: name,
    task_content: body,
    needs_review: needsReview,
    facilities: classified.facilities,
    amenities: classified.amenities,
    ...profile
  }
}];
